    {
        if (!dataTypes.TryGetValue(name, out DataTypeUsageBuilder? usage))
            dataTypes[name] = usage = new DataTypeUsageBuilder(name);
        return usage;
    }

    public void RecordGlobal(string name, string type, bool isOptional)
